/**
 * CryptoEze payment helpers shared by the payments API route and the
 * checkout UI. Kept dependency-light and pure so the provider response
 * parsing and QR payload resolution can be unit-tested directly.
 *
 * Provider API (https://cryptoeze.com/docs), confirmed by CryptoEze admin:
 *   POST /api/v1/pkr      { method: "qr", amount, order_id, ... }
 *     -> 200 { data: { id, status: "pending", checkout_url, qr_string } }
 *   GET  /api/v1/pkr/{id} -> same shape for an already-created payment
 *
 * `qr_string` is the scan-to-pay QR payload generated by CryptoEze for the
 * order. `checkout_url` is the hosted checkout page URL. The two are never
 * interchangeable: the on-page QR image is rendered ONLY from `qr_string`,
 * while `checkout_url` is used ONLY as the fallback "Open Payment Page"
 * link. The payment QR is never fabricated from `checkout_url`.
 */
import QRCode from "qrcode";

/** Raw `data` object returned by the CryptoEze create/resume payment endpoints. */
export type CryptoEzePaymentData = {
  id: string;
  status: string | null;
  checkout_url: string;
  qr_string: string | null;
  order_id: string | null;
};

/** Normalized, validated view of the provider payment data used by the app. */
export type ParsedCryptoEzePayment = {
  id: string;
  status: string | null;
  checkoutUrl: string;
  qrString: string | null;
  /** `order_id` echoed by the provider; null when the field is absent. */
  providerOrderId: string | null;
};

/**
 * Parse the CryptoEze create/resume payment response body. Returns null when
 * the payload is malformed or the required `id`/`checkout_url` fields are
 * missing, so callers can map it to a safe error instead of trusting garbage.
 *
 * `qr_string` is treated as optional: the documented response always includes
 * it, but a missing or non-string value must degrade the UI to the
 * "Open Payment Page" fallback — never to a QR fabricated from checkout_url.
 */
export function parseCryptoEzePaymentData(
  payload: unknown
): ParsedCryptoEzePayment | null {
  const data = (payload as { data?: unknown } | null | undefined)?.data;
  if (typeof data !== "object" || data === null) return null;
  const rec = data as Record<string, unknown>;

  if (typeof rec.id !== "string" || rec.id.length === 0) return null;
  if (typeof rec.checkout_url !== "string" || rec.checkout_url.length === 0) {
    return null;
  }

  return {
    id: rec.id,
    status: typeof rec.status === "string" ? rec.status : null,
    checkoutUrl: rec.checkout_url,
    qrString:
      typeof rec.qr_string === "string" && rec.qr_string.length > 0
        ? rec.qr_string
        : null,
    providerOrderId: typeof rec.order_id === "string" ? rec.order_id : null,
  };
}

export type QrRenderSource =
  | { kind: "qr_string"; value: string }
  | { kind: "checkout_fallback"; value: string }
  | { kind: "none" };

/**
 * Decide what the checkout UI renders. The payment QR image is generated
 * ONLY from the provider-returned `qr_string`. When it is missing or blank,
 * the UI degrades to the `checkout_url` link (kind: "checkout_fallback") —
 * it must never encode `checkout_url` (or anything else) as a QR.
 */
export function resolveQrRenderSource(input: {
  qrString?: string | null;
  checkoutUrl?: string | null;
}): QrRenderSource {
  if (typeof input.qrString === "string" && input.qrString.trim().length > 0) {
    return { kind: "qr_string", value: input.qrString };
  }
  if (
    typeof input.checkoutUrl === "string" &&
    input.checkoutUrl.trim().length > 0
  ) {
    return { kind: "checkout_fallback", value: input.checkoutUrl };
  }
  return { kind: "none" };
}

/** Rendering options for the on-page payment QR (512px, M error correction). */
export const PAYMENT_QR_OPTIONS = {
  errorCorrectionLevel: "M",
  margin: 2,
  width: 512,
} as const;

/**
 * Render the payment QR PNG (as a data URL) from the exact payload passed in.
 * Callers must only ever pass the provider-returned `qr_string` here — see
 * `resolveQrRenderSource`, the single gatekeeper for that rule.
 */
export async function buildPaymentQrDataUrl(payload: string): Promise<string> {
  // Fresh object per call: the qrcode package mutates the options object it
  // receives (merging defaults), so a shared reference would get polluted
  // across renders/requests.
  return QRCode.toDataURL(payload, { ...PAYMENT_QR_OPTIONS });
}
